-- V107 configurable service-level objectives and aggregate evaluation evidence.
CREATE TABLE IF NOT EXISTS service_level_objectives(tenant_id text NOT NULL,objective_key text NOT NULL,version integer NOT NULL CHECK(version>=1),metric_key text NOT NULL,target_ratio numeric NOT NULL CHECK(target_ratio>0 AND target_ratio<=1),window_ms bigint NOT NULL CHECK(window_ms>=60000),minimum_events bigint NOT NULL CHECK(minimum_events>=1),definition_hash char(64) NOT NULL,defined_by_hash char(64) NOT NULL,defined_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,objective_key,version));CREATE TABLE IF NOT EXISTS service_level_evaluations(seq bigserial PRIMARY KEY,id text UNIQUE NOT NULL,tenant_id text NOT NULL,objective_key text NOT NULL,objective_version integer NOT NULL,status text NOT NULL CHECK(status IN('NO_DATA','HEALTHY','BREACHED')),good bigint NOT NULL,total bigint NOT NULL,definition_hash char(64) NOT NULL,evaluated_at timestamptz NOT NULL);ALTER TABLE service_level_objectives ENABLE ROW LEVEL SECURITY;ALTER TABLE service_level_objectives FORCE ROW LEVEL SECURITY;ALTER TABLE service_level_evaluations ENABLE ROW LEVEL SECURITY;ALTER TABLE service_level_evaluations FORCE ROW LEVEL SECURITY;CREATE POLICY slo_objective_tenant ON service_level_objectives USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE POLICY slo_evaluation_tenant ON service_level_evaluations USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));CREATE OR REPLACE FUNCTION deny_slo_evaluation_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'service level evaluation evidence is append only'; END $$;CREATE TRIGGER slo_evaluations_append_only BEFORE UPDATE OR DELETE ON service_level_evaluations FOR EACH ROW EXECUTE FUNCTION deny_slo_evaluation_mutation();
